  (2524, 'Oct 2025 - OpenVC.xlsx', 'Bedford Bridge', 'Venture Fund', 'Seed, Series A, Series B, Series C, Growth', 'https://www.bedfordbridge.com/', 'We invest in high performance healthcare companies at the convergence of technology and biology. We focus on 4 key themes: connectivity, platform innovation, payments and deep technology. This includes: distributed care, virtual care, wearables, patient empowerment, artificial intelligence, mental health and holistic care solutions, chronic disease management, data analysis, alternative drug pricing, value-based care, care efficiency, preventative medicine, synthetic biology, nanotechnology, personalized medicine, gene editing, and more', '', '', '', '220 Riverside Blvd, New York, NY 10069', 'New York', 40.7128, -74.006, '', '', '', 0, 0, 'We invest in high performance healthcare companies at the convergence of technology and biology. We focus on 4 key themes: connectivity, platform innovation, payments and deep technology. This includes: distributed care, virtual care, wearables, patient empowerment, artificial intelligence, mental health and holistic care solutions, chronic disease management, data analysis, alternative drug pricing, value-based care, care efficiency, preventative medicine, synthetic biology, nanotechnology, personalized medicine, gene editing, and more Invests in: USA,Canada,Israel,UK First cheque: $2,000,000 - $20,000,000', null),
  (2525, 'Oct 2025 - OpenVC.xlsx', 'Beeso Studio', 'Startup studio', 'Pre-Seed, Seed', 'https://www.beeso.io/', 'We partner with early-stage software startups to apply expertise in software development, operations, marketing, sales and fundraising to help you launch and scale. The best technical partner to get software startups from 0-1.', '', '', '', '6818 Grover St Suite #107, Omaha, NE 68106', '6818 Grover St Suite #107', null, null, '', '', '', 0, 0, 'We partner with early-stage software startups to apply expertise in software development, operations, marketing, sales and fundraising to help you launch and scale. The best technical partner to get software startups from 0-1. Invests in: USA First cheque: $0 - $0', null),
