  (3649, 'Oct 2025 - OpenVC.xlsx', 'Peaceful Progress', 'Venture Fund', 'Series A, Series B, Series C, Growth', 'https://www.peacefulprogress.in/', 'We invest in Tech-focused and Consumer-driven Startups leveraging our 20+ investments in these sectors generating minimum 6 exits at 2X MOIC in the next 4 years. Peaceful Progress Fund is a US $10 million seed fund in Chennai, India.', '', '', '', 'No. 5/27, Door No.9, 3rd Floor, 10th Avenue (Opp Sri Krishna Sweets), Ashok Nagar, Chennai 600083', 'No. 5', null, null, '', '', '', 0, 0, 'We invest in Tech-focused and Consumer-driven Startups leveraging our 20+ investments in these sectors generating minimum 6 exits at 2X MOIC in the next 4 years. Peaceful Progress Fund is a US $10 million seed fund in Chennai, India. Invests in: India First cheque: $130,000 - $400,000', null),
  (3650, 'Oct 2025 - OpenVC.xlsx', 'Peak', 'Venture Fund', 'Pre-Seed, Seed, Series A', 'https://www.peak.capital', 'We invest in SaaS and Platform/Marketplaces businesses in NW-Europe. Our sweetspot is companies that have some revenue, and are getting ready to scale beyond founder sales. Opportunistically we do pre-revenue/pre-product deals. No sector/industry focus.', '', '', '', 'Weesperplein 4B, 1018 XA Amsterdam, Netherlands', 'Amsterdam', 52.3676, 4.9041, '', '', '', 0, 0, 'We invest in SaaS and Platform/Marketplaces businesses in NW-Europe. Our sweetspot is companies that have some revenue, and are getting ready to scale beyond founder sales. Opportunistically we do pre-revenue/pre-product deals. No sector/industry focus. Invests in: Austria,Belgium,Denmark,Finland,Germany,Iceland,Luxembourg,Netherlands,Norway,Poland,Portugal,Sweden,Switzerland First cheque: $200,000 - $3,000,000', null),
